import java.io.*;
import java.util.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static boolean hasMore() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        if (c == -1) return false;
        ptr--;
        return true;
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = read();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        nextInt(); // n
        int[] a = new int[16];
        int m = 0, top = 0;
        while (hasMore()) {
            if (m == a.length) a = Arrays.copyOf(a, m * 2);
            a[m] = nextInt();
            top = Math.max(top, a[m++]);
        }
        char[] before = new char[m], after = new char[m];
        boolean[] seen = new boolean[top + 1];
        for (int i = 0; i < m; i++) {
            before[i] = seen[a[i]] ? '1' : '0';
            seen[a[i]] = true;
        }
        Arrays.fill(seen, false);
        for (int i = m - 1; i >= 0; i--) {
            after[i] = seen[a[i]] ? '1' : '0';
            seen[a[i]] = true;
        }
        System.out.println(new String(before) + "\n" + new String(after));
    }
}

package main

import (
	"bufio"
	"io"
	"os"
	"slices"
)

var data []byte
var pos int

func skip() {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
}

func nextInt() int64 {
	skip()
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func hasMore() bool {
	skip()
	return pos < len(data)
}

func main() {
	data, _ = io.ReadAll(bufio.NewReader(os.Stdin))
	nextInt() // n
	var a []int64
	for hasMore() {
		a = append(a, nextInt())
	}
	m := len(a)
	top := int64(0)
	if m > 0 {
		top = slices.Max(a)
	}
	before := make([]byte, m)
	after := make([]byte, m)
	seen := make([]bool, top+1)
	for i, v := range a {
		before[i] = '0'
		if seen[v] {
			before[i] = '1'
		}
		seen[v] = true
	}
	clear(seen)
	for i := m - 1; i >= 0; i-- {
		after[i] = '0'
		if seen[a[i]] {
			after[i] = '1'
		}
		seen[a[i]] = true
	}
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	w.Write(before)
	w.WriteByte('\n')
	w.Write(after)
	w.WriteByte('\n')
}
